export STATE_DIR="$(mktemp -d)" && node --input-type=module -e '
import assert from "node:assert/strict";
const b = await import("./bot.mjs");
const now = new Date("2026-10-23T10:00:00Z");
const d = (s) => new Date(s);
const M = (to, kind = "marketing") => ({ to, kind });

// fresh address: marketing allowed (no opt-out recorded)
assert.deepEqual(await b.mayEmail(M("buyer@example.com"), now), { allowed: true, reason: null });

// unsubscribe via header-style address with different case
await b.recordUnsubscribe("\"Ayse\" <Buyer+promo@Example.com>", d("2026-10-22T09:00:00Z"));
assert.deepEqual(await b.mayEmail(M("buyer@example.com"), now), { allowed: false, reason: "unsubscribed" });
assert.deepEqual(await b.mayEmail(M("b.u.y.e.r@example.com"), now), { allowed: false, reason: "unsubscribed" }); // domain/local same person? (non-gmail: dots differ, so allowed)
' ; echo "exit=$?"

export STATE_DIR="$(mktemp -d)" && node --input-type=module -e '
import assert from "node:assert/strict";
import { existsSync } from "node:fs";
const b = await import("./bot.mjs");
const now = new Date("2026-10-23T10:00:00Z");
const d = (s) => new Date(s);
const M = (to, kind = "marketing") => ({ to, kind });
const OK = { allowed: true, reason: null };
const NO = { allowed: false, reason: "unsubscribed" };

assert.deepEqual(await b.mayEmail(M("buyer@example.com"), now), OK);
await b.recordUnsubscribe("\"Ayse\" <Buyer+promo@Example.com>", d("2026-10-22T09:00:00Z"));
assert.deepEqual(await b.mayEmail(M("buyer@example.com"), now), NO, "unsub blocks marketing, alias+case");
assert.deepEqual(await b.mayEmail(M("b.uyer@example.com"), now), OK, "non-gmail dots are a different mailbox");
assert.deepEqual(await b.mayEmail(M("buyer@example.com", "transactional"), now), OK, "receipts still allowed");
assert.deepEqual(await b.mayEmail(M("buyer@example.com", "weird"), now), { allowed: false, reason: "unknown_kind" });
assert.deepEqual(await b.mayEmail(M("not-an-address", "marketing"), now), { allowed: false, reason: "invalid_recipient" });

// out-of-order: an older resubscribe arriving late must not clear a newer unsubscribe
await b.recordResubscribe("buyer@example.com", d("2026-10-21T00:00:00Z"));
assert.deepEqual(await b.mayEmail(M("buyer@example.com"), now), NO, "stale resub does not clear");

// a deliberate resubscribe after the unsubscribe clears it
await b.recordResubscribe("buyer@example.com", d("2026-10-23T08:00:00Z"));
assert.deepEqual(await b.mayEmail(M("buyer@example.com"), now), OK, "newer resub clears");

// a later unsubscribe (arriving first or last) blocks again
await b.recordUnsubscribe("buyer@example.com", d("2026-10-23T09:00:00Z"));
assert.deepEqual(await b.mayEmail(M("buyer@example.com"), now), NO, "newer unsub blocks again");

// concurrent writes from several workers all land
await Promise.all(Array.from({ length: 20 }, (_, i) => b.recordUnsubscribe("race@example.org", d(`2026-10-20T00:00:${String(i).padStart(2, "0")}Z`))));
assert.deepEqual(await b.mayEmail(M("race@example.org"), now), NO, "concurrent unsubs");

// state read fresh every call: a new process-level write is seen without re-import
assert.deepEqual(await b.mayEmail(M("fresh@example.net"), now), OK);
await b.recordUnsubscribe("fresh@example.net", d("2026-10-23T09:59:00Z"));
assert.deepEqual(await b.mayEmail(M("fresh@example.net"), now), NO, "fresh read");

// fail closed: unreadable state blocks marketing, transactional unaffected
delete process.env.STATE_DIR;
assert.deepEqual(await b.mayEmail(M("buyer@example.com"), now), { allowed: false, reason: "opt_out_state_unavailable" });
assert.deepEqual(await b.mayEmail(M("buyer@example.com", "transactional"), now), OK);

console.log("all checks passed");
' ; echo "exit=$?"; ls "$STATE_DIR" 2>/dev/null; find "${TMPDIR:-/tmp}" -maxdepth 1 -name 'tmp.*' -newer bot.mjs 2>/dev/null | head -0; find . -name '*.tmp' | head -0
